`tf_text(user, g)` builds the raw evaluation text from a prompt and a generation row. Next I assemble the candidate diagnostic texts and count their tokens:
- R: the edited runaway math answers, with the answer truncated to its first 2,500 tokens, which covers the onset of degeneration (at about 500–1,100 tokens);
- W: start's wandering math answers that recover, full;
- N: a few clean math answers, full;
- I: prose copies taken from the p12 texts.

If the padded size, texts × longest length × 27.6 KB, exceeds the 6 GB cap, I will drop the longest texts or the hidden-state layers.

```python
# Hypothesis: most diagnostic texts are under ~12k tokens; pick a set whose padded mlp_act[10,13,14]+hidden[11,14,15] size fits in 6 GB.
G11s, G11e = load_pass(11); G14s, G14e = load_pass(14)
byid = lambda G: {idx(g): g for g in G}
P11S, P11E, P14S, P14E = map(byid, (G11s, G11e, G14s, G14e))
math_prompt = lambda k, mset: P[200 + k] if mset is ps['MATH_C'] else None
p11p = json.load(open('/work/p11_prompts.json')); p14p = json.load(open('/work/p14_prompts.json'))
def ntoks(s): return len(tok.encode(s))
# R: edited runaways (answer > 6000 chars, failed)
R_items = []
for k, Gp, prompts, mset in ((11, P11E, p11p, ps['MATH_S']), (14, P14E, p14p, ps['MATH_S']), (16, E16, P, ps['MATH_C'])):
    M = grade_math([g for g in Gp.values() if 200 <= idx(g) < 224], mset, off=200)
    for i, g in Gp.items():
        if 200 <= i < 224 and '</think>' in g['text'] and not M[(i - 200, 0)]['ok'] and len(g['text'].split('</think>')[-1]) > 6000:
            R_items.append((k, i, prompts[i], g))
# W: start wanders that recover (from code run 197)
W_ids = [(11, 205), (14, 209), (16, 201), (16, 206), (16, 212), (16, 219), (16, 223)]
srcS = {11: (P11S, p11p), 14: (P14S, p14p), 16: (S16, P)}
W_items = [(k, i, srcS[k][1][i], srcS[k][0][i]) for k, i in W_ids]
for nm, items in (('R', R_items), ('W', W_items)):
    for k, i, pr, g in items:
        t = g['text']; p = t.find('</think>')
        print(nm, k, i, 'prompt+think tok %d, answer tok %d, fin %s' % (ntoks(pr) + ntoks(t[:p + 8]), ntoks(t[p + 8:]), g['finish_reason']))
```

P17 is back. Before analysing it, I want to reuse the kernel's existing detector machinery (exact MLP-input reconstruction, normalized drives, joint drive c, phase projections). Then the numbers stay comparable with earlier sessions: c ≈ 1 at copies and loops, about 0 at natural ends. This block prints only the signatures and argument names of those helpers and the contents of the small constants (DET, LIDX, HIDX, DIRS, BN, GAM, …); it computes nothing.

```python
# Hypothesis: kernel helpers (mlp_in, normacts, drives, c_joint, det_norm) and constants (DET, LIDX, DIRS, BN, GAM) let me compute start/PF5C5 drives and phase on P17 directly.
for nm in ('mlp_in', 'detacts', 'normacts', 'drives', 'drives_on', 'c_joint', 'joint', 'det_norm', 'c_mod', 's10_of', 'x13', 'silu_np', 'region_masks', 'regions'):
    fn = globals()[nm]; co = fn.__code__
    print('%-12s %s | locals %s | names %s' % (nm, inspect.signature(fn), co.co_varnames[co.co_argcount:co.co_argcount + 8], [n for n in co.co_names][:12]))
def brief(v):
    if isinstance(v, dict): return {k: (brief(x) if not hasattr(x, 'shape') else ('arr', x.shape)) for k, x in list(v.items())[:8]}
    if hasattr(v, 'shape'): return ('arr', v.shape)
    if isinstance(v, (list, tuple)): return v[:10] if len(v) <= 10 else (v[:6], '... len %d' % len(v))
    return v
for nm in ('DET', 'DET10', 'DET7', 'LIDX', 'LIDX7', 'HIDX', 'DIRS', 'BN', 'GAM', 'GSTAR', 'K_', 'M_', 'LN', 'CFGS'):
    print(nm, '=', brief(globals()[nm]))
```

That explains the mismatch. The kernel variable DIRS is a different direction (cosine 0.42 with the edit). The edit itself was built exactly from `answer_dirs_v1.npz`: cosine 1.000, with scale ratios equal to the β and γ values. So the phase numbers in my last two tables were computed on the wrong direction.

I will recompute the phase projection with the real edit directions (pA_l = d_l^v1 · x̃_l) and redo the comparison. The comparison sets are:
- prose copies (A);
- math wanders and runaways (W, R) at high drive;
- start's three re-close points;
- thinking at high drive.

The decisive question is the same as before: is pA clearly lower at the math re-close and wander positions than at prose copies? If so, a phase threshold could keep the re-close while still suppressing copies.

```python
# Hypothesis: with the true edit direction (answer_dirs_v1) the math wander / re-close positions have intermediate pA (~0.4-0.7), prose copies ~1, explaining PF5C5's partial suppression there.
DA = {l: torch.as_tensor(AD['d%d' % l], dtype=torch.float32) for l in (10, 13, 14)}
for r in REC:
    i, n = r['i'], r['n']; pa = np.zeros((3, n), np.float32)
    for li, l in enumerate((10, 13, 14)):
        h = torch.from_numpy(HS[i, HI[l], :n].astype(np.float32)); a = torch.from_numpy(MA[i, li, :n].astype(np.float32))
        rr = h - a @ Wd[l].T
        xt = rr * torch.rsqrt((rr * rr).mean(1, keepdim=True) + eps_) * (1 + wpost[l])
        pa[li] = (xt @ DA[l]).numpy()
    r['pa'] = pa
rows = []
for r in REC:
    i, te, n = r['i'], r['te'], r['n']; cat = classify_ans(TK[i, :n], r['ast'], te, n)
    for t, c in cat.items(): rows.append((r['grp'], c, r['c0'][t], r['c5'][t], *r['pa'][:, t]))
    for t in range(r['ast'] + 8, te): rows.append((r['grp'], 'think', r['c0'][t], r['c5'][t], *r['pa'][:, t]))
DA17 = pd.DataFrame(rows, columns=['grp', 'cat', 'c0', 'c5', 'pa10', 'pa13', 'pa14'])
hiA = DA17[DA17.c0 > 0.75]
print('all positions:'); print(DA17.groupby(['grp', 'cat'])[['pa10', 'pa13', 'pa14']].median().round(2).T.to_string())
print('high-drive (c0>0.75):'); print(hiA.groupby(['grp', 'cat']).agg(n=('c0', 'size'), c0=('c0', 'median'), c5=('c5', 'median'), pa10=('pa10', 'median'), pa13=('pa13', 'median'), pa14=('pa14', 'median')).round(2).T.to_string())
for r in REC:
    if r['grp'] != 'W' or meta17[r['i']]['truncated']: continue
    i, te, n = r['i'], r['te'], r['n']; tks = TK[i, :n]
    for t in [int(t) for t in np.where(tks == THK)[0] if t > te]:
        w = slice(t - 20, t)
        print('W %s re-close: c0 %.2f c5 %.2f | pa10 %.2f pa13 %.2f pa14 %.2f' % (meta17[i]['id'], r['c0'][w].mean(), r['c5'][w].mean(), *r['pa'][:, w].mean(1)))
```

The best refit (shrinkage 0.1, "pre" kept as positive) improves on the old direction only partly:
- **Degenerate math answers:** the unwanted suppression falls from about 0.3 of the copy level to 0.14–0.21.
- **High-drive thinking:** it stays near zero (0.02–0.06), so the loop exit is safe.
- **Clean math answers:** they stay at 0.75–0.84.

Since degenerate states lie between thinking and clean answers in this representation, a linear direction cannot push them all the way to 0.

To know whether this is enough, I need the effect on the drive itself. For both directions, with the same β and γ and the new direction rescaled to give the same projection at copies, I will compute the single-layer drive estimate at:
- start's three re-close windows;
- the degenerate high-drive positions of the held-out R/W texts;
- prose copies;
- high-drive thinking;
- the last answer tokens of natural endings (negative-lobe side effects).

**Decision rule.** If the new direction brings the re-close windows back near start's drive (c0 0.63–1.02), it is worth a teacher-forced check of </think> probabilities. If it recovers only a small part, I will consider strengthening the re-close by other means.

```python
# Hypothesis: with the refit direction (same betas, matched copy scale) the drive at re-close windows / degenerate math answers returns most of the way to start, while prose copies stay suppressed.
NEWd = {l: fit_dir2(l, 0.1, ('copyA', 'ansB', 'ansC', 'ansD', 'pre'), ('think', 'loopE', 'deg_hi', 'think_hi'), ('think', 'loopE', 'deg_hi', 'think_hi')) for l in (10, 13, 14)}
te_ = LABd.split.values == 'test'
for l in (10, 13, 14):   # match the copy-level projection of OLD
    NEWd[l] = NEWd[l] * (np.median(X[l][te_ & (LABd.cat2.values == 'copyA')] @ OLD[l]) / np.median(X[l][te_ & (LABd.cat2.values == 'copyA')] @ NEWd[l]))
def drive_with(xs, dirs, scale=1.0):
    # xs: list of x~ (n x 1024) for layers 10,13,14 ; returns s (5 x n) under PF5C5-type edit with directions dirs
    s = []
    for (l, nn, al) in DET:
        x = xs[(10, 13, 14).index(l)]; p_ = x @ dirs[l]
        zg = x @ G0[l][nn].numpy(); zu = x @ U0[l][nn].numpy()
        if (l, nn) in ((10, 59), (10, 120), (14, 239)): zg = zg - scale * BN[(l, nn)] * p_
        elif (l, nn) == (13, 16): zu = zu - scale * 0.5 * p_
        elif (l, nn) == (13, 7): zu = zu + scale * 0.25 * p_
        s.append(zg / (1 + np.exp(-zg)) * zu / al)
    return np.array(s)
def xs_p17(i, ts):
    out = []
    for li, l in enumerate((10, 13, 14)):
        h = torch.from_numpy(HS[i, HI[l], ts].astype(np.float32)); a = torch.from_numpy(MA[i, li, ts].astype(np.float32))
        rr = h - a @ Wd[l].T; out.append((rr * torch.rsqrt((rr * rr).mean(1, keepdim=True) + eps_) * (1 + wpost[l])).numpy())
    return out
res = []
for r in REC:
    i, te, n, gname = r['i'], r['te'], r['n'], r['grp']; tid = meta17[i]['id']; held = (gname, tid) not in TRAIN17
    sets = {}
    tks = TK[i, :n]
    if gname == 'W':
        for t in [int(t) for t in np.where(tks == THK)[0] if t > te]: sets['reclose'] = np.arange(t - 20, t)
    if gname in ('W', 'R'):
        o = onset_of(r['c0'][te + 1:n]); post = np.arange(te + 1 + o, n); sets['deg_hi'] = post[r['c0'][post] > 0.75]
    if gname == 'A': sets['copy'] = np.arange(te + 1, n)
    if gname in ('N', 'C'): sets['natend'] = np.arange(n - 6, n - 1)
    th = np.arange(r['ast'] + 1, te); sets['think_hi'] = th[r['c0'][th] > 0.75]
    for k_, ts in sets.items():
        if len(ts) == 0: continue
        ts = np.sort(ts); xs = xs_p17(i, ts)
        c_old = 0.5 * drive_with(xs, OLD).sum(0); c_new = 0.5 * drive_with(xs, NEWd).sum(0)
        res.append((gname, tid, held, k_, len(ts), r['c0'][ts].mean(), c_old.mean(), c_new.mean()))
RS17 = pd.DataFrame(res, columns=['grp', 'id', 'held', 'set', 'n', 'c0', 'c_PF5C5', 'c_NEW'])
print(RS17.round(2).to_string())
```

The thinking side effect is no worse than PF5C5's. On the P2 texts the new direction matches the old one:
- loop drive at the synthetic loops (E): 1.06 for the new direction, 1.05 for the old, 1.12 for start;
- new crossings above 0.75 in thinking: about equal;
- prose copies: answer drive −0.19 for both.

At the re-close windows themselves the new direction still projects about 0.2–0.5 of the copy level, so it does not remove the partial suppression where start actually re-closed. Its gain is confined to the broader degenerate stretches.

One more lever is the overall strength. PF5C5 overshoots at prose copies: the drive becomes negative (about −0.2 to −0.46), so there the edit pushes against ending, which may also delay legitimate endings. P16 shows small losses on max_words and end_phrase.

I will scan a common scale factor (0.6–1.0) on all five edit vectors with the new direction, and compare it with PF5C5 (old direction, scale 1.0), on:
- prose copies (P2 and P17 A answers, A stop points);
- natural ends of non-copy prose (B);
- held-out degenerate math answers;
- the re-close windows;
- high-drive thinking.

The aim is the smallest scale that keeps the copy drive at or below about 0.1. Every point of strength below 1.0 gives back drive at the intermediate, degenerate positions.

```python
# Hypothesis: copies are over-suppressed (negative drive), so a scale ~0.75-0.85 on the NEW edit keeps copy drive <= ~0.1 while returning more drive at degenerate math answers / re-close windows.
def collect_sets():
    S = {'copyP2': [], 'stopA': [], 'endB': [], 'thinkhi': [], 'loopE': [], 'deg_held': [], 'reclose': [], 'copyP17': []}
    for i in range(len(meta2)):
        g2 = meta2[i][0]; tks = T2[i]; n = int((tks >= 0).sum()); tks = tks[:n]
        te = int(np.where(tks == THK)[0][0]) if (tks == THK).any() else n; ast = int(np.where(tks == IMS)[0][-1])
        xs, c0 = xt_all(HS2, MA2, i, n); th = np.arange(ast + 1, te)
        take = lambda ts: ([x[ts] for x in xs], c0[ts])
        if g2 == 'A': S['copyP2'].append(take(np.arange(te + 1, n - 1))); S['stopA'].append(take(np.arange(n - 3, n - 1)))
        if g2 == 'B': S['endB'].append(take(np.arange(n - 3, n - 1)))
        if g2 == 'E': S['loopE'].append(take(th[c0[th] > 0.75]))
        else: S['thinkhi'].append(take(th[c0[th] > 0.75]))
    for r in REC:
        i, te, n, gname = r['i'], r['te'], r['n'], r['grp']; held = (gname, meta17[i]['id']) not in TRAIN17; tks = TK[i, :n]
        if gname == 'A': ts = np.arange(te + 1, n); S['copyP17'].append((xs_p17(i, ts), r['c0'][ts]))
        if gname in ('W', 'R') and held:
            o = onset_of(r['c0'][te + 1:n]); post = np.arange(te + 1 + o, n); ts = post[r['c0'][post] > 0.75]; S['deg_held'].append((xs_p17(i, ts), r['c0'][ts]))
        if gname == 'W':
            for t in [int(t) for t in np.where(tks == THK)[0] if t > te]: ts = np.arange(t - 20, t); S['reclose'].append((xs_p17(i, ts), r['c0'][ts]))
    return {k: ([np.concatenate([v[0][j] for v in L]) for j in range(3)], np.concatenate([v[1] for v in L])) for k, L in S.items() if L}
SETS17 = collect_sets()
print({k: len(v[1]) for k, v in SETS17.items()})
rows = []
for name, dirs, scales in (('OLD', OLD, (1.0,)), ('NEW', NEWd, (0.6, 0.7, 0.8, 0.9, 1.0))):
    for sc in scales:
        row = {'dir': name, 'scale': sc}
        for k, (xs, c0) in SETS17.items():
            row[k] = float(np.mean(0.5 * drive_with(xs, dirs, sc).sum(0)))
        rows.append(row)
row = {'dir': 'start', 'scale': 0}
for k, (xs, c0) in SETS17.items(): row[k] = float(np.mean(c0))
rows.append(row)
print(pd.DataFrame(rows).round(2).to_string())
```

